insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-pharmaceutics-note-101','Pharmacy','Diploma in Pharmacy','note','free',101,'{"title":"Pharmaceutics: Dosage Forms and Classification","english":"Dosage forms are pharmaceutical preparations designed to deliver a medicine safely and effectively. Major groups include solid forms (tablets, capsules, powders, granules, lozenges, suppositories), liquid forms (solutions, syrups, elixirs, suspensions, emulsions, drops), semisolid forms (ointments, creams, gels, pastes) and sterile preparations (injections and infusions). Selection depends on the drug, patient, route, stability and intended release.","nepali":"Dosage form भनेको औषधिलाई सुरक्षित र प्रभावकारी रूपमा दिन तयार गरिएको रूप हो। मुख्य समूहमा solid (tablet, capsule, powder), liquid (solution, syrup, suspension, emulsion), semisolid (ointment, cream, gel) र sterile preparations (injection, infusion) पर्छन्। औषधिको गुण, बिरामी, दिने मार्ग, stability र औषधि छुट्ने तरिकाअनुसार dosage form छनोट गरिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-note-102','Pharmacy','Diploma in Pharmacy','note','free',102,'{"title":"Pharmacopoeias and Formularies","english":"A pharmacopoeia is an official publication containing standards for the identity, strength, quality and purity of medicines, together with test methods. Examples include the British Pharmacopoeia (BP), United States Pharmacopeia (USP), Indian Pharmacopoeia (IP), European Pharmacopoeia and International Pharmacopoeia. A formulary is a selected list of medicines approved or recommended for use in a health-care system or institution.","nepali":"Pharmacopoeia औषधिको पहिचान, शक्ति, गुणस्तर र शुद्धताका आधिकारिक मापदण्ड तथा परीक्षण विधि भएको पुस्तक/प्रकाशन हो। उदाहरण: BP, USP, IP, European Pharmacopoeia र International Pharmacopoeia। Formulary भनेको स्वास्थ्य संस्था वा प्रणालीमा प्रयोगका लागि छनोट/स्वीकृत औषधिहरूको सूची हो।"}'::jsonb,true),
('dph-pharmaceutics-note-103','Pharmacy','Diploma in Pharmacy','note','free',103,'{"title":"Weights, Measures and Strength Expressions","english":"Pharmaceutical calculations require accurate conversion between metric units. Common relationships include 1 g = 1000 mg, 1 mg = 1000 micrograms, and 1 L = 1000 mL. Percentage strength may be expressed as % w/w (grams in 100 g), % w/v (grams in 100 mL) or % v/v (mL in 100 mL). Ratio strength expresses one part of solute in a stated number of parts of final preparation. Always check units before calculating or dispensing.","nepali":"Pharmaceutical calculation मा metric unit सही रूपान्तरण गर्नुपर्छ: 1 g = 1000 mg, 1 mg = 1000 microgram र 1 L = 1000 mL। Percentage strength % w/w (100 g मा कति gram), % w/v (100 mL मा कति gram) वा % v/v (100 mL मा कति mL) हुन सक्छ। Ratio strength ले अन्तिम तयारीको निश्चित भागमा solute को एक भाग जनाउँछ। Calculation अघि unit जाँच्नुहोस्।"}'::jsonb,true),
('dph-pharmaceutics-note-104','Pharmacy','Diploma in Pharmacy','note','free',104,'{"title":"Pharmaceutical Processing and Stability","english":"Important processing operations include comminution (size reduction), size separation, mixing and homogenization, filtration and clarification, extraction, heating, distillation and drying. Stability is the ability of a product to remain within established quality specifications during storage. Temperature, light, moisture, oxygen, pH and packaging can affect stability. Follow the labelled storage conditions and expiry date; do not use products with compromised packaging or uncertain quality.","nepali":"मुख्य processing operations मा comminution (कण सानो बनाउने), size separation, mixing/homogenization, filtration, extraction, heating, distillation र drying पर्छन्। Stability भनेको भण्डारण अवधिभर औषधि तोकिएको गुणस्तरभित्र रहन सक्ने क्षमता हो। तापक्रम, प्रकाश, चिस्यान, oxygen, pH र packaging ले stability असर गर्न सक्छन्। Label मा लेखिएको storage condition र expiry पालना गर्नुहोस्।"}'::jsonb,true),
('dph-pharmaceutics-note-105','Pharmacy','Diploma in Pharmacy','note','free',105,'{"title":"Dispersed Systems and Biopharmaceutics","english":"A solution is a homogeneous single-phase system. A suspension contains insoluble solid particles dispersed in a liquid and may require shaking before use. An emulsion is a dispersion of one immiscible liquid in another, stabilized by an emulsifying agent. Bioavailability describes the rate and extent to which the active ingredient becomes available at the site of action or, for systemic medicines, reaches systemic circulation.","nepali":"Solution एकरूप (homogeneous) single-phase system हो। Suspension मा नघुल्ने ठोस कण liquid मा फैलिएका हुन्छन् र प्रयोगअघि हल्लाउनुपर्ने हुन सक्छ। Emulsion मा एक-अर्कामा नमिसिने liquid मध्ये एउटा अर्कोमा फैलिएको हुन्छ र emulsifying agent ले स्थिर बनाउँछ। Bioavailability ले सक्रिय औषधि site of action वा systemic circulation मा पुग्ने दर र परिमाण जनाउँछ।"}'::jsonb,true),
('dph-pharmaceutics-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',101,'{"question":"Which dosage form is generally a solid unit containing a measured dose of medicine, often with excipients?","translation":"सामान्यतया excipients सहित औषधिको निश्चित मात्रा भएको solid unit कुन हो?","options":["Tablet","Syrup","Emulsion","Liniment"],"correctIndex":0,"explanation":"A tablet is a solid unit dosage form containing an accurately measured amount of medicine.","explanationNe":"Tablet निश्चित मात्राको औषधि भएको solid unit dosage form हो।"}'::jsonb,true),
('dph-pharmaceutics-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',102,'{"question":"Which official publication provides standards for the quality and purity of medicines?","translation":"औषधिको गुणस्तर र शुद्धताका मापदण्ड कुन आधिकारिक प्रकाशनले दिन्छ?","options":["Pharmacopoeia","Invoice","Patient card","Purchase requisition"],"correctIndex":0,"explanation":"Pharmacopoeias contain official standards and test methods for medicines.","explanationNe":"Pharmacopoeia मा औषधिका आधिकारिक मापदण्ड र परीक्षण विधि हुन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',103,'{"question":"How many milligrams are present in 2 grams?","translation":"२ gram मा कति milligram हुन्छ?","options":["20 mg","200 mg","2000 mg","20000 mg"],"correctIndex":2,"explanation":"1 g equals 1000 mg; therefore 2 g equals 2000 mg.","explanationNe":"१ g = १००० mg भएकाले २ g = २००० mg हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',104,'{"question":"A 5% w/v solution contains how many grams of solute in 100 mL of final solution?","translation":"५% w/v solution को १०० mL मा solute कति gram हुन्छ?","options":["0.5 g","5 g","50 g","100 g"],"correctIndex":1,"explanation":"Percent w/v means grams of solute in 100 mL of final preparation.","explanationNe":"% w/v को अर्थ अन्तिम १०० mL तयारीमा solute को gram हो; त्यसैले ५ g।"}'::jsonb,true),
('dph-pharmaceutics-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',105,'{"question":"Which process reduces the particle size of a solid drug material?","translation":"ठोस औषधिको कणको आकार घटाउने प्रक्रिया कुन हो?","options":["Comminution","Filtration","Distillation","Clarification"],"correctIndex":0,"explanation":"Comminution is the size-reduction operation.","explanationNe":"Comminution भनेको कणको आकार घटाउने प्रक्रिया हो।"}'::jsonb,true),
('dph-pharmaceutics-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',106,'{"question":"Which dosage form is a dispersion of insoluble solid particles in a liquid?","translation":"Liquid मा नघुल्ने ठोस कण फैलिएको dosage form कुन हो?","options":["Solution","Suspension","Elixir","Aromatic water"],"correctIndex":1,"explanation":"A suspension contains insoluble solid particles dispersed in a liquid vehicle.","explanationNe":"Suspension मा नघुल्ने ठोस कण liquid vehicle मा फैलिएका हुन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',107,'{"question":"Which dosage form consists of one immiscible liquid dispersed in another?","translation":"एक-अर्कामा नमिसिने liquid मध्ये एउटा अर्कोमा फैलिएको dosage form कुन हो?","options":["Emulsion","Solution","Powder","Tablet"],"correctIndex":0,"explanation":"An emulsion is a dispersed system of two immiscible liquids.","explanationNe":"Emulsion दुई नमिसिने liquid को dispersed system हो।"}'::jsonb,true),
('dph-pharmaceutics-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',108,'{"question":"Which factor can commonly accelerate pharmaceutical degradation?","translation":"कुन कारणले औषधिको degradation छिटो हुन सक्छ?","options":["Excess heat and moisture","Correct labelling","Proper storage","Intact packaging"],"correctIndex":0,"explanation":"Heat and moisture can accelerate many degradation pathways; product-specific storage instructions must be followed.","explanationNe":"धेरै औषधिमा ताप र चिस्यानले degradation बढाउन सक्छ; औषधिअनुसारको storage instruction पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmaceutics-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',109,'{"question":"What does % v/v express?","translation":"% v/v ले के जनाउँछ?","options":["Grams per 100 g","Grams per 100 mL","mL per 100 mL","Parts per million"],"correctIndex":2,"explanation":"% v/v expresses millilitres of solute in 100 mL of final preparation.","explanationNe":"% v/v ले अन्तिम १०० mL तयारीमा solute को mL जनाउँछ।"}'::jsonb,true),
('dph-pharmaceutics-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',110,'{"question":"Which statement best describes bioavailability for a systemic medicine?","translation":"Systemic medicine को bioavailability लाई कुन भनाइले राम्रोसँग जनाउँछ?","options":["Rate and extent reaching systemic circulation","Tablet colour and shape","Only medicine shelf life","Only packaging size"],"correctIndex":0,"explanation":"Bioavailability describes the rate and extent of active drug reaching systemic circulation.","explanationNe":"Bioavailability ले सक्रिय औषधि systemic circulation मा पुग्ने दर र परिमाण जनाउँछ।"}'::jsonb,true),
